const assert = require('node:assert/strict');
const { ProfileService } = require('../.build/service');
const { parseProfile } = require('../.build/parser');

function fresh() { return new ProfileService({ displayName: 'before', tags: ['old'] }); }
function throws(fn) { assert.throws(fn, /invalid profile/); }

// -------- shape of the input --------
// Arrays, null and nonobjects are invalid.
throws(() => fresh().patch([]));
throws(() => fresh().patch(null));
throws(() => fresh().patch(undefined));
throws(() => fresh().patch('str'));
throws(() => fresh().patch(42));
throws(() => fresh().patch(0));
throws(() => fresh().patch(true));
throws(() => fresh().patch(() => {}));

// Only Object.prototype or null prototypes are accepted.
throws(() => fresh().patch(Object.create({ x: 1 })));
throws(() => fresh().patch(Object.assign(Object.create({}), { displayName: 'ok' })));
class Klass { }
throws(() => fresh().patch(new Klass()));
const nullProto = Object.assign(Object.create(null), { displayName: 'accept null proto' });
assert.deepEqual(fresh().patch(nullProto), { displayName: 'accept null proto', tags: ['old'] });

// Unknown keys are invalid, even when other fields are valid; storage untouched.
throws(() => fresh().patch({ extra: 1 }));
throws(() => fresh().patch({ unknown: null }));
throws(() => fresh().patch({ displayName: 'ok', tags: ['a'], extra: 1 }));
throws(() => fresh().patch({ nested: {} }));

// -------- displayName --------
// Absent field retains the stored value.
assert.deepEqual(fresh().patch({ tags: ['x'] }), { displayName: 'before', tags: ['x'] });
// Empty object is a valid no-op.
assert.deepEqual(fresh().patch({}), { displayName: 'before', tags: ['old'] });
// null clears it.
assert.deepEqual(fresh().patch({ displayName: null }), { displayName: null, tags: ['old'] });
// Strings are trimmed before the length check and stored trimmed.
assert.deepEqual(fresh().patch({ displayName: '  spaced  ' }), { displayName: 'spaced', tags: ['old'] });
assert.deepEqual(fresh().patch({ displayName: '\t\n tab \r\n' }), { displayName: 'tab', tags: ['old'] });
assert.deepEqual(fresh().patch({ displayName: ' ' + 'x'.repeat(40) + ' ' }),
  { displayName: 'x'.repeat(40), tags: ['old'] });
// Length 0 or >40 after trimming is invalid (no numbers/booleans coerced).
throws(() => fresh().patch({ displayName: '' }));
throws(() => fresh().patch({ displayName: ' \t\r\n ' }));
throws(() => fresh().patch({ displayName: 'x'.repeat(41) }));
throws(() => fresh().patch({ displayName: ' ' + 'x'.repeat(41) }));
throws(() => fresh().patch({ displayName: 42 }));
throws(() => fresh().patch({ displayName: 0 }));
throws(() => fresh().patch({ displayName: true }));
throws(() => fresh().patch({ displayName: {} }));
throws(() => fresh().patch({ displayName: ['ok'] }));

// -------- tags --------
// null and [] both clear tags.
assert.deepEqual(fresh().patch({ tags: null }), { displayName: 'before', tags: [] });
assert.deepEqual(fresh().patch({ tags: [] }), { displayName: 'before', tags: [] });
// Valid list: trimmed, distinct, sized.
assert.deepEqual(fresh().patch({ tags: [' a ', 'b'] }), { displayName: 'before', tags: ['a', 'b'] });
assert.deepEqual(fresh().patch({ tags: ['x'.repeat(12)] }), { displayName: 'before', tags: ['x'.repeat(12)] });
assert.deepEqual(fresh().patch({ tags: ['1', '2', '3', '4', '5'] }),
  { displayName: 'before', tags: ['1', '2', '3', '4', '5'] });
// More than five entries, duplicates after trimming, empty/oversized after
// trimming and non-string entries (no numeric coercion) are all invalid.
throws(() => fresh().patch({ tags: ['1', '2', '3', '4', '5', '6'] }));
throws(() => fresh().patch({ tags: ['a', 'a'] }));
throws(() => fresh().patch({ tags: ['a', ' a ' ] }));
throws(() => fresh().patch({ tags: [' a ', 'a'] }));
throws(() => fresh().patch({ tags: [''] }));
throws(() => fresh().patch({ tags: ['   '] }));
throws(() => fresh().patch({ tags: ['\t'] }));
throws(() => fresh().patch({ tags: ['x'.repeat(13)] }));
throws(() => fresh().patch({ tags: [' x'.repeat(13) + ' '] }));
throws(() => fresh().patch({ tags: [1, 'ok'] }));
throws(() => fresh().patch({ tags: [42] }));
throws(() => fresh().patch({ tags: [null] }));
throws(() => fresh().patch({ tags: [true] }));
throws(() => fresh().patch({ tags: [{}] }));
throws(() => fresh().patch({ tags: {} }));
throws(() => fresh().patch({ tags: 'a,b' }));
throws(() => fresh().patch({ tags: ['ok'], extra: false }));

// -------- atomicity and aliasing --------
// Any invalid field leaves storage unchanged, even with other valid fields present.
const guard = new ProfileService({ displayName: 'keep', tags: ['keep'] });
throws(() => guard.patch({ displayName: 'x', tags: [1] }));
assert.deepEqual(guard.profile, { displayName: 'keep', tags: ['keep'] });
const guard2 = new ProfileService({ displayName: 'keep', tags: ['keep'] });
throws(() => guard2.patch({ displayName: 9, tags: ['valid'] }));
assert.deepEqual(guard2.profile, { displayName: 'keep', tags: ['keep'] });

// The input object is never modified and the caller's tags array is not reused.
const input = { displayName: '  in  ', tags: [' t1 ', 't2'] };
const svc = fresh();
const result = svc.patch(input);
assert.deepEqual(input, { displayName: '  in  ', tags: [' t1 ', 't2'] });
assert.deepEqual(result, { displayName: 'in', tags: ['t1', 't2'] });
input.tags.push('mutated by caller');
assert.deepEqual(svc.profile.tags, ['t1', 't2']);
assert.notEqual(svc.profile.tags, input.tags);
input.displayName = 'clobbered';
assert.equal(svc.profile.displayName, 'in');

// Parser contract: keep/set kinds and fresh arrays per call.
assert.deepEqual(parseProfile({}), { displayName: { kind: 'keep' }, tags: { kind: 'keep' } });
const parsed = parseProfile({ displayName: ' a ', tags: [' b '] });
assert.deepEqual(parsed, { displayName: { kind: 'set', value: 'a' }, tags: { kind: 'set', value: ['b'] } });
const parsedNullName = parseProfile({ displayName: null, tags: null });
assert.deepEqual(parsedNullName, { displayName: { kind: 'set', value: null }, tags: { kind: 'set', value: [] } });
throws(() => parseProfile('nope'));

console.log('contract checks passed');

